import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as s,o,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Claude Code Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/claude/claude-code-glossary.md","filePath":"products/ai-coding/claude/claude-code-glossary.md","lastUpdated":1787040327000}'),n={name:"products/ai-coding/claude/claude-code-glossary.md"};function r(i,e,l,d,c,p){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="claude-code-glossary" tabindex="-1">Claude Code Glossary <a class="header-anchor" href="#claude-code-glossary" aria-label="Permalink to &quot;Claude Code Glossary&quot;">​</a></h1><blockquote><p>This is an <strong>explanatory</strong> document — answering &quot;what is this concept, why is it designed this way, when should I use it.&quot; It complements the <a href="./claude-code-cheatsheet.html">Claude Code Cheatsheet</a>: the cheatsheet answers &quot;how to configure, what are the parameters, how to choose,&quot; while this document answers &quot;what is this, why is it needed, how does it relate to other concepts.&quot;</p><p><strong>All terms shared across chapters</strong> are defined here in one place. The main tutorial <a href="./claude-code.html">Claude Code</a> and <a href="./claude-code-cookbook.html">Practical Cookbook</a> reference this page, avoiding redundant explanations and inconsistent descriptions.</p></blockquote><h2 id="concept-map" tabindex="-1">Concept Map <a class="header-anchor" href="#concept-map" aria-label="Permalink to &quot;Concept Map&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌─────────────┐</span></span>
<span class="line"><span>                    │   MCP Protocol│  ← Lowest-level open protocol</span></span>
<span class="line"><span>                    │ (Open Standard)│</span></span>
<span class="line"><span>                    └──────┬──────┘</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>              ┌────────────┼────────────┐</span></span>
<span class="line"><span>              │            │            │</span></span>
<span class="line"><span>         ┌────┴────┐  ┌───┴───┐  ┌────┴────┐</span></span>
<span class="line"><span>         │ Hooks   │  │Skills │  │Connectors│  ← Different wrappers based on MCP</span></span>
<span class="line"><span>         │ (Hooks)  │  │(Skills)│  │(Connectors)│</span></span>
<span class="line"><span>         └────┬────┘  └───┬───┘  └──────────┘</span></span>
<span class="line"><span>              │           │</span></span>
<span class="line"><span>              └─────┬─────┘</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>              ┌─────┴─────┐</span></span>
<span class="line"><span>              │  Plugins  │  ← Package the above capabilities into installable units</span></span>
<span class="line"><span>              │  (Plugins)   │</span></span>
<span class="line"><span>              └───────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>External Collaboration      ┌─────────────┐  ┌─────────────┐</span></span>
<span class="line"><span>                            │ Sub-agents  │  │  Memory     │</span></span>
<span class="line"><span>                            │ (Sub-agents)    │ (Memory)      │</span></span>
<span class="line"><span>                            └─────────────┘  └─────────────┘</span></span></code></pre></div><p><strong>Core Logic</strong>: MCP is the lowest-level open protocol, defining how Claude communicates with external tools. Hooks, Skills, and Connectors are different abstraction layers built on MCP. Plugins package Skills + Agents + Hooks + MCP into an installable unit. Sub-agents and Memory run parallel to the above mainline — they are independent dimensions for &quot;multi-agent collaboration&quot; and &quot;cross-conversation memory.&quot;</p><hr><h2 id="mcp-model-context-protocol" tabindex="-1">MCP (Model Context Protocol) <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP (Model Context Protocol)&quot;">​</a></h2><p><strong>What It Is</strong>: An open standard protocol defining how AI applications (like Claude) securely communicate with external tools, databases, and APIs. Think of it as the &quot;USB interface&quot; of the AI world — any tool following the protocol can plug in and work.</p><p><strong>Why It Matters</strong>: Before MCP, each AI tool needed to implement its own logic for connecting to external services — connecting to GitHub, databases, and Slack all required separate implementations. With MCP:</p><ul><li><strong>Tool developers</strong> only need to implement an MCP server once, and all MCP-supporting AIs can use it</li><li><strong>Users</strong> only need to configure connections once, then share them across Claude Code, Claude.ai, and Claude Desktop</li><li><strong>Ecosystem</strong>: Over 1000 tools including GitHub, databases, Slack, Jira already have MCP server implementations</li></ul><p><strong>Role in the Claude Ecosystem</strong>:</p><table tabindex="0"><thead><tr><th>Layer</th><th>MCP-Based Capability</th><th>Description</th></tr></thead><tbody><tr><td>Claude Code CLI</td><td><code>claude mcp add</code> to add MCP servers</td><td>Local processes or HTTP servers</td></tr><tr><td>Claude.ai / Desktop</td><td>Connectors</td><td>Cloud MCP servers with one-click OAuth authorization</td></tr><tr><td>Plugins</td><td><code>.mcp.json</code> configuration</td><td>MCP server definitions embedded in plugins</td></tr><tr><td>Custom Tools</td><td>Custom MCP servers</td><td>Connect to internal or self-built tools</td></tr></tbody></table><p><strong>Two Transport Methods</strong>:</p><table tabindex="0"><thead><tr><th>Method</th><th>Use Case</th><th>Configuration Example</th></tr></thead><tbody><tr><td><strong>stdio</strong></td><td>Local processes (databases, CLI tools)</td><td><code>claude mcp add --transport stdio db -- npx -y @bytebase/dbhub</code></td></tr><tr><td><strong>HTTP/SSE</strong></td><td>Remote services (cloud APIs, internal services)</td><td><code>claude mcp add --transport http github https://api.github.com/mcp/</code></td></tr></tbody></table><p><strong>Official Docs</strong>:</p><ul><li><a href="https://code.claude.com/docs/en/mcp" target="_blank" rel="noreferrer">MCP Development Guide</a></li><li><a href="https://modelcontextprotocol.io/servers" target="_blank" rel="noreferrer">MCP Registry</a></li><li><a href="https://code.claude.com/docs/en/cli-reference#mcp" target="_blank" rel="noreferrer">Claude Code MCP Reference</a></li></ul><hr><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p><strong>What It Is</strong>: A folder containing instructions, scripts, and resources that Claude dynamically loads to improve stability on specialized tasks. Simply put: skills make Claude more professional and stable for specific tasks.</p><p><strong>Two Types of Skills</strong>:</p><table tabindex="0"><thead><tr><th>Type</th><th>Location</th><th>Description</th></tr></thead><tbody><tr><td><strong>Project Skills</strong></td><td><code>.claude/skills/&lt;name&gt;/SKILL.md</code></td><td>Project-shared, committed to Git</td></tr><tr><td><strong>User Skills</strong></td><td><code>~/.claude/skills/&lt;name&gt;/SKILL.md</code></td><td>Personal global, applies to all projects</td></tr></tbody></table><p><strong>Core Mechanism</strong>:</p><ol><li>Claude analyzes the current task during conversation</li><li>Matches against the <code>description</code> field in the Skills directory</li><li>Automatically loads the corresponding <code>SKILL.md</code> instructions when matched</li><li>Can also be manually invoked with <code>/skill-name</code></li></ol><p><strong>Difference from Commands</strong>:</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Commands</th><th>Skills</th></tr></thead><tbody><tr><td>Trigger</td><td>Manual <code>/command</code></td><td>Auto-recognition + manual</td></tr><tr><td>Structure</td><td>Single <code>.md</code> file</td><td>Directory with resources (<code>SKILL.md</code> + scripts)</td></tr><tr><td>Complexity</td><td>Simple prompts</td><td>Multi-file, multi-step workflows</td></tr></tbody></table><p><strong>SKILL.md Example</strong>:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">code-reviewer</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Use when user requests code review, PR review, or code quality checks</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tools</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Read, Grep, Glob</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">You are a senior code review expert. Please check the following aspects:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Security vulnerabilities (OWASP Top 10)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Performance issues</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Code style consistency</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">4.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Test coverage</span></span></code></pre></div><p><strong>Official Docs</strong>:</p><ul><li><a href="https://code.claude.com/docs/en/skills" target="_blank" rel="noreferrer">Skills Development Guide</a></li><li><a href="https://support.claude.com/en/articles/12512198" target="_blank" rel="noreferrer">Claude.ai Skills</a></li></ul><hr><h2 id="hooks" tabindex="-1">Hooks <a class="header-anchor" href="#hooks" aria-label="Permalink to &quot;Hooks&quot;">​</a></h2><p><strong>What It Is</strong>: Scripts that <strong>automatically trigger</strong> before or after Claude Code tool calls, enabling automated workflows. For example: auto-format after saving files, run lint before commits, load environment variables at session start.</p><p><strong>Why Hooks Are Needed</strong>: Skills are loaded by Claude based on <strong>judgment</strong> of whether they match the scenario (semantic matching), while Hooks <strong>always</strong> trigger on specific events (deterministic, like &quot;run format on every save&quot;). They complement each other.</p><p><strong>Common Trigger Events</strong>:</p><table tabindex="0"><thead><tr><th>Event</th><th>Trigger Timing</th><th>Typical Use</th></tr></thead><tbody><tr><td><code>PreToolUse</code></td><td>Before tool call</td><td>Intercept dangerous operations, modify parameters</td></tr><tr><td><code>PostToolUse</code></td><td>After tool call</td><td>Auto-format, lint, test</td></tr><tr><td><code>SessionStart</code></td><td>Session start</td><td>Load environment variables, initialize</td></tr><tr><td><code>SessionEnd</code></td><td>Session end</td><td>Cleanup, reporting</td></tr><tr><td><code>UserPromptSubmit</code></td><td>User submits message</td><td>Logging, validation</td></tr><tr><td><code>ConfigChange</code></td><td>Config file changes</td><td>Reload custom config</td></tr></tbody></table><blockquote><p>For complete event list and <code>if</code> condition syntax, see <a href="https://code.claude.com/docs/en/hooks-guide" target="_blank" rel="noreferrer">Hooks Reference</a> and <a href="./claude-code-cheatsheet.html#hook-configuration">cheatsheet · Hook Configuration</a>.</p></blockquote><p><strong>Three Hook Types</strong>:</p><table tabindex="0"><thead><tr><th>Type</th><th>Description</th><th>Use Case</th></tr></thead><tbody><tr><td><code>command</code></td><td>Execute shell commands</td><td>Format, lint, test</td></tr><tr><td><code>prompt</code></td><td>Inject additional prompt to Claude</td><td>Dynamically inject context</td></tr><tr><td><code>mcp_tool</code></td><td>Call MCP server</td><td>Complex external integrations</td></tr></tbody></table><p><strong>Official Docs</strong>:</p><ul><li><a href="https://code.claude.com/docs/en/hooks-guide" target="_blank" rel="noreferrer">Hooks Development Guide</a></li><li><a href="https://code.claude.com/docs/en/hooks-guide" target="_blank" rel="noreferrer">Hooks Reference</a></li></ul><hr><h2 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h2><p><strong>What It Is</strong>: An <strong>independent unit</strong> that extends Claude Code capabilities, capable of packaging Skills, Agents, Hooks, MCP servers, and other features for cross-project reuse and team sharing. A plugin is essentially a <strong>directory</strong> containing several components.</p><p><strong>Plugin-Component Relationship</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Plugin (Plugin)</span></span>
<span class="line"><span>├── skills/        ← Skills</span></span>
<span class="line"><span>├── agents/        ← Sub-agents</span></span>
<span class="line"><span>├── hooks/         ← Hooks</span></span>
<span class="line"><span>├── .mcp.json      ← MCP servers</span></span>
<span class="line"><span>├── .lsp.json      ← LSP servers</span></span>
<span class="line"><span>└── settings.json  ← Default configuration</span></span></code></pre></div><p><strong>Plugins vs Skills</strong>: A plugin is a &quot;packaged capability bundle,&quot; while a skill is just one component. You can use skills alone (copy directly to <code>.claude/skills/</code>), or package multiple skills into a plugin for distribution (npm / Git / Marketplace).</p><p><strong>Two Installation Scopes</strong>:</p><table tabindex="0"><thead><tr><th>Scope</th><th>Storage Location</th><th>Description</th></tr></thead><tbody><tr><td><code>--scope user</code></td><td><code>~/.claude/plugins/cache/</code></td><td>User-level, applies to all projects (default)</td></tr><tr><td><code>--scope project</code></td><td><code>.claude/</code></td><td>Current project only (commit to Git for team sharing)</td></tr></tbody></table><p><strong>Plugin Sources</strong>:</p><table tabindex="0"><thead><tr><th>Source</th><th>Description</th></tr></thead><tbody><tr><td><strong>npm</strong></td><td><code>claude plugin install @company/ai-kit</code></td></tr><tr><td><strong>Git</strong></td><td>Install from GitHub/GitLab repositories</td></tr><tr><td><strong>Local directory</strong></td><td><code>claude --plugin-dir ./my-plugin</code></td></tr></tbody></table><p><strong>Official Docs</strong>:</p><ul><li><a href="https://code.claude.com/docs/en/plugins-reference" target="_blank" rel="noreferrer">Plugins Reference</a></li><li><a href="https://code.claude.com/docs/en/plugin-marketplaces" target="_blank" rel="noreferrer">Marketplace</a></li><li><a href="https://code.claude.com/docs/en/plugins" target="_blank" rel="noreferrer">Claude Code Plugins</a></li></ul><hr><h2 id="sub-agents" tabindex="-1">Sub-agents <a class="header-anchor" href="#sub-agents" aria-label="Permalink to &quot;Sub-agents&quot;">​</a></h2><p><strong>What It Is</strong>: AI assistants with <strong>independent persona, permissions, and toolsets</strong>. The main agent can spawn multiple sub-agents to handle different tasks in parallel, then merge the results.</p><p><strong>Why Needed</strong>: In complex tasks, a single agent processing everything causes &quot;context pollution&quot; — long conversations mix exploration, implementation, and review, interfering with each other&#39;s thinking. Sub-agents give each subtask its own <strong>clean, independent context window</strong>.</p><p><strong>Two Types of Sub-agents</strong>:</p><table tabindex="0"><thead><tr><th>Type</th><th>Description</th><th>Configuration Location</th></tr></thead><tbody><tr><td><strong>Built-in</strong></td><td>Explore (codebase exploration), Plan (planning and research)</td><td>System-built, no configuration needed</td></tr><tr><td><strong>Custom</strong></td><td>Specialized agents you define</td><td><code>.claude/agents/&lt;name&gt;.md</code></td></tr></tbody></table><p><strong>Custom Sub-agent Example</strong>:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- .claude/agents/security-reviewer.md --&gt;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name: security-reviewer</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: Invoke when security review, permission vulnerability checks, or OWASP compliance is needed</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tools: Read, Grep, Glob</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model: claude-opus-4-6</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">permissionMode: ask</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">You are a code review expert focused on web security, skilled at identifying OWASP Top 10 vulnerabilities.</span></span></code></pre></div><p><strong>Use Cases</strong>:</p><ul><li>Large task decomposition: Have multiple agents review different modules in parallel</li><li>Specialized division of labor: Separate agents for security review, performance analysis, test generation</li><li>Model selection: Use Sonnet for simple tasks, Opus for complex tasks</li><li><strong>Context isolation</strong>: Avoid long tasks polluting the main conversation context</li></ul><p><strong>Key Constraints</strong>:</p><ul><li><strong>No nested sub-agents</strong>: Sub-agents cannot delegate to sub-agents</li><li><strong>Context isolation</strong>: Each sub-agent has an independent context window, seeing neither the main agent&#39;s nor other sub-agents&#39; conversations</li><li><strong>Parallel execution</strong>: Multiple sub-agents can run simultaneously, each consuming their respective model&#39;s quota</li></ul><p><strong>Official Docs</strong>: <a href="https://code.claude.com/docs/en/sub-agents" target="_blank" rel="noreferrer">Sub-agents Guide</a></p><hr><h2 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;Memory&quot;">​</a></h2><p><strong>What It Is</strong>: Enables Claude to <strong>remember across conversations</strong> your preferences, background information, and work habits, so you don&#39;t need to reintroduce yourself each time.</p><p><strong>Two Complementary Memory Types</strong>:</p><table tabindex="0"><thead><tr><th>Mechanism</th><th>Who Writes</th><th>Purpose</th><th>Storage Location</th></tr></thead><tbody><tr><td><strong>CLAUDE.md</strong></td><td>You manually write</td><td>Project specs, tech stack, coding conventions</td><td><code>.claude/CLAUDE.md</code> (committed to Git)</td></tr><tr><td><strong>Auto Memory</strong></td><td>Claude automatically writes</td><td>Build commands, debugging findings, architecture decisions</td><td><code>~/.claude/projects/&lt;project&gt;/memory/</code></td></tr></tbody></table><p><strong>Why Two Systems</strong>: CLAUDE.md addresses stable rules that &quot;you tell Claude&quot; (team/project specifications); Auto Memory addresses dynamic knowledge that &quot;Claude learns itself&quot; (&quot;yesterday&#39;s debugging found this API returns 500 in test environment&quot;). The former is specification, the latter is personal notes.</p><p><strong>CLAUDE.md Loading Hierarchy</strong> (for complete rules and scope table, see <a href="./claude-code-cheatsheet.html#configuration-scopes">cheatsheet · Settings Scope</a>):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Managed policy (enterprise/system, highest priority)</span></span>
<span class="line"><span>    └── ~/.claude/CLAUDE.md (user global)</span></span>
<span class="line"><span>        └── .claude/CLAUDE.md (project-shared, committed to Git)</span></span>
<span class="line"><span>            └── .claude/CLAUDE.local.md (personal local override, not committed)</span></span></code></pre></div><p><strong>Auto Memory Indexing Mechanism</strong>:</p><ul><li><strong>Index file</strong>: <code>MEMORY.md</code> — automatically loads first 200 lines (~25KB) at startup</li><li><strong>Each memory</strong>: Independent <code>.md</code> file with frontmatter (name, description, type, timestamp)</li><li><strong>Memory types</strong>: User preferences (user), feedback (feedback), project knowledge (project), external references (reference)</li><li><strong>Auto-linking</strong>: Memories link to each other via <code>[[memory-name]]</code></li></ul><p><strong>Official Docs</strong>: <a href="https://code.claude.com/docs/en/memory" target="_blank" rel="noreferrer">Memory System</a></p><hr><h2 id="dynamic-workflows" tabindex="-1">Dynamic Workflows <a class="header-anchor" href="#dynamic-workflows" aria-label="Permalink to &quot;Dynamic Workflows&quot;">​</a></h2><p><strong>What It Is</strong>: The capability to orchestrate large-scale sub-agent workflows via JavaScript scripts. Claude writes the scripts, and the runtime executes them — elevating multi-agent collaboration from &quot;manual scheduling&quot; to &quot;scripted pipelines.&quot;</p><p><strong>Why Needed</strong>: Sub-agents suit medium-scale scenarios where &quot;the main agent manually spawns a few sub-agents.&quot; For <strong>massive parallelism</strong> (like reviewing 100 PRs simultaneously) or <strong>reusable pipelines</strong> (build → test → deploy), script orchestration is more maintainable than manual scheduling.</p><p><strong>Core APIs</strong>:</p><table tabindex="0"><thead><tr><th>API</th><th>Purpose</th><th>Pattern</th></tr></thead><tbody><tr><td><code>agent()</code></td><td>Launch multiple sub-agents in parallel</td><td>Fan-out</td></tr><tr><td><code>pipeline()</code></td><td>Execute multi-step pipelines sequentially</td><td>Sequential</td></tr></tbody></table><p><strong>Built-in Workflows</strong>:</p><table tabindex="0"><thead><tr><th>Workflow</th><th>Trigger</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/deep-research</code></td><td>Slash command</td><td>Multi-round deep research with auto-generated reports</td></tr><tr><td><code>ultracode</code></td><td>Keyword</td><td>Auto code review + fix workflow</td></tr></tbody></table><p><strong>Usage Limitations</strong>:</p><ul><li>Beta phase, APIs may change</li><li>No nested sub-agents</li><li>Subject to <code>maxThinkingTokens</code> limit</li><li>Case-sensitive: <code>Agent()</code> and <code>AGENT()</code> are invalid</li></ul><p><strong>Official Docs</strong>: <a href="https://code.claude.com/docs/en/workflows" target="_blank" rel="noreferrer">Dynamic Workflows</a></p><hr><h2 id="cross-session-messaging" tabindex="-1">Cross-Session Messaging <a class="header-anchor" href="#cross-session-messaging" aria-label="Permalink to &quot;Cross-Session Messaging&quot;">​</a></h2><p><strong>What It Is</strong>: Send plain text messages between different Claude Code sessions, enabling multi-session collaboration. <strong>Plain text</strong> means no files, no full conversation history can be transferred — this is a built-in security boundary.</p><p><strong>Why Needed</strong>: When working in parallel across multiple sessions (one on backend, one on frontend), sessions need to synchronize signals like &quot;I&#39;m done, you can continue,&quot; rather than requiring users to manually copy.</p><p><strong>Core Tools</strong>:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>ListAgents</code></td><td>List currently available Claude Code sessions</td></tr><tr><td><code>SendMessage</code></td><td>Send text messages to specified sessions</td></tr></tbody></table><p><strong>@mention Syntax</strong>:</p><ul><li><code>@session-abc</code> — Mention by session ID</li><li><code>@~/project-name</code> — Mention by project path</li></ul><p><strong>Receiving Settings</strong> (for complete configuration parameters, see <a href="./claude-code-cheatsheet.html#permission-configuration">cheatsheet · Permission Configuration</a>):</p><table tabindex="0"><thead><tr><th>Setting</th><th>Optional Values</th><th>Description</th></tr></thead><tbody><tr><td><code>crossSessionInbound</code></td><td>accept / hold / refuse</td><td>Message receiving policy</td></tr><tr><td><code>isolatePeerMachines</code></td><td>true / false</td><td>Whether to isolate other machines on the same network</td></tr><tr><td><code>dialogExpiry</code></td><td>Time string</td><td>Dialog expiration time</td></tr></tbody></table><p><strong>Security Rules</strong>:</p><ul><li>Plain text only, cannot send files or conversation history</li><li>Messages can only come from registered sessions</li><li>All cross-session messages are auditable</li></ul><p><strong>Official Docs</strong>: <a href="https://code.claude.com/docs/en/cross-session-messaging" target="_blank" rel="noreferrer">Cross-Session Messaging</a></p><hr><h2 id="agent-teams-experimental" tabindex="-1">Agent Teams (Experimental) <a class="header-anchor" href="#agent-teams-experimental" aria-label="Permalink to &quot;Agent Teams (Experimental)&quot;">​</a></h2><p><strong>What It Is</strong>: An experimental feature that organizes multiple Claude Code sessions into a team, with a Lead assigning tasks, Teammates executing in parallel, and sharing a task list.</p><p><strong>Difference from Sub-agents</strong>:</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Sub-agents</th><th>Agent Teams</th></tr></thead><tbody><tr><td>Isolation Level</td><td>Same terminal process</td><td>Independent sessions (can use split-pane)</td></tr><tr><td>Context</td><td>Shares main agent context</td><td><strong>Completely isolated</strong> independent contexts</td></tr><tr><td>Coordination</td><td>Main agent manually spawns</td><td>Shared task list + Lead assignment</td></tr><tr><td>Scale</td><td>A few parallel sub-tasks</td><td>Complex collaboration with role-based division</td></tr></tbody></table><p><strong>Roles</strong>:</p><table tabindex="0"><thead><tr><th>Role</th><th>Responsibility</th></tr></thead><tbody><tr><td><strong>Lead</strong></td><td>Create tasks, assign tasks, approve proposals, monitor progress</td></tr><tr><td><strong>Teammate</strong></td><td>Claim tasks, execute, report results</td></tr></tbody></table><p><strong>Teammate Modes</strong>:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td><strong>In-process</strong></td><td>Runs within same terminal process, shares context</td></tr><tr><td><strong>Split-panes</strong></td><td>Independent terminals (tmux/iTerm2), fully isolated</td></tr></tbody></table><p><strong>Constraints</strong>:</p><ul><li>No nested teams (one session, one team)</li><li>Sub-agents can register as teammates</li><li>Enable with <code>CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS=1</code></li></ul><p><strong>Official Docs</strong>: <a href="https://code.claude.com/docs/en/agent-teams" target="_blank" rel="noreferrer">Agent Teams</a></p><hr><h2 id="remote-control" tabindex="-1">Remote Control <a class="header-anchor" href="#remote-control" aria-label="Permalink to &quot;Remote Control&quot;">​</a></h2><p><strong>What It Is</strong>: Connect claude.ai web, Claude mobile app, or Slack to your local Claude Code session for remote interaction.</p><p><strong>Why Needed</strong>: A long task runs locally (build, test, deploy), and you want to check progress from your phone or add a new instruction temporarily. Remote Control makes this &quot;remote append&quot; an officially supported capability.</p><p><strong>Three Connection Modes</strong>:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Flag/Command</th><th>Description</th></tr></thead><tbody><tr><td><strong>Server</strong></td><td><code>claude --remote-control</code></td><td>Continuously listen for remote connections</td></tr><tr><td><strong>Interactive</strong></td><td><code>/remote-control</code> or <code>/rc</code></td><td>Accept one-time connection</td></tr><tr><td><strong>SSH Forwarding</strong></td><td>SSH tunnel</td><td>Remote machine exposes local port via SSH</td></tr></tbody></table><p><strong>Security Mechanism — Trusted Devices</strong>:</p><ul><li>First connection requires biometric authentication (fingerprint / Face ID)</li><li>Trust validity: 18 hours</li><li><code>/remote-control logout</code> immediately revokes</li><li>Mobile push notifications + Presence Heartbeats (heartbeat detects connection activity)</li></ul><p><strong>Official Docs</strong>: <a href="https://code.claude.com/docs/en/remote-control" target="_blank" rel="noreferrer">Remote Control</a></p><hr><h2 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h2><p><strong>What It Is</strong>: Push events from external messaging sources (Telegram, Discord, iMessage) into Claude Code sessions, enabling task triggering from non-Claude interfaces.</p><p><strong>Why Needed</strong>: Remote Control is &quot;controlling local sessions from Claude interfaces&quot;; Channels is the reverse — &quot;triggering Claude tasks from external messaging sources you already use (Telegram/Discord/iMessage).&quot; The latter better suits collaboration scenarios where &quot;non-Claude users need Claude&#39;s help.&quot;</p><p><strong>Supported Channels</strong>:</p><table tabindex="0"><thead><tr><th>Channel</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Telegram</td><td>MCP plugin</td><td>Trigger tasks from Telegram conversations</td></tr><tr><td>Discord</td><td>MCP plugin</td><td>Receive commands from Discord channels</td></tr><tr><td>iMessage</td><td>MCP plugin (Bun)</td><td>Trigger tasks from iMessage conversations</td></tr></tbody></table><p><strong>Key Features</strong>:</p><ul><li>Enable with <code>--channels</code> flag</li><li>Permission relay: Channel messages automatically go through permission flow</li><li>Sender allowlist: Restrict who can send</li><li>Status: Research Preview phase</li></ul><p><strong>Official Docs</strong>: <a href="https://code.claude.com/docs/en/channels" target="_blank" rel="noreferrer">Channels</a></p><hr><h2 id="worktree" tabindex="-1">Worktree <a class="header-anchor" href="#worktree" aria-label="Permalink to &quot;Worktree&quot;">​</a></h2><p><strong>What It Is</strong>: Uses Git&#39;s <code>git worktree</code> feature to let multiple Claude Code sessions <strong>work in parallel on different branches of the same project</strong>, without interference.</p><p><strong>Why Needed</strong>: In traditional mode, one Claude Code session occupies one working directory. To work on two features in parallel, you manually switch branches, causing frequent conflicts. Worktree gives each session an independent directory and branch for true parallelism.</p><p><strong>Core Value</strong>:</p><ul><li><strong>Parallel development</strong>: One session works on feature A, another on feature B</li><li><strong>Session isolation</strong>: Each session has independent working directory and Git state</li><li><strong>Automatic management</strong>: Claude Code automatically creates and cleans worktrees</li></ul><p><strong>CLI Flag</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --worktree</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/claude-worktree-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p><strong>Isolation Checks</strong> (Claude Code automatically verifies 4 conditions before starting a session):</p><ol><li>Whether working directory is within original repository</li><li>Whether Git index is clean</li><li>Whether there are uncommitted changes</li><li>Whether pointing to correct remote branch</li></ol><p><strong>Official Docs</strong>: <a href="https://code.claude.com/docs/en/worktrees" target="_blank" rel="noreferrer">Worktree Deep Dive</a></p><hr><h2 id="permission-modes" tabindex="-1">Permission Modes <a class="header-anchor" href="#permission-modes" aria-label="Permalink to &quot;Permission Modes&quot;">​</a></h2><p><strong>What It Is</strong>: Controls whether Claude asks you before executing operations. It&#39;s the most frequently used &quot;decision parameter&quot; in daily use — choosing the wrong mode either floods you with confirmation popups or removes safety boundaries.</p><p><strong>Five Modes</strong> (for complete comparison table and decision guide, see <a href="./claude-code-cheatsheet.html#which-permission-mode-to-use">cheatsheet · Which Permission Mode to Use</a>):</p><table tabindex="0"><thead><tr><th>Display Name</th><th>Configuration Value</th><th>Behavior</th><th>When to Use</th></tr></thead><tbody><tr><td><strong>Normal</strong></td><td><code>default</code></td><td>Ask for confirmation before execution</td><td>Default, most cautious</td></tr><tr><td><strong>Auto</strong></td><td><code>auto</code></td><td>AI classifier auto-decides: safe operations auto-approve, dangerous operations blocked</td><td>Recommended: no frequent confirmations, retains safety boundaries</td></tr><tr><td><strong>Plan</strong></td><td><code>plan</code></td><td>Read-only analysis, no changes</td><td>Plan first, act later</td></tr><tr><td><strong>Accept Edits</strong></td><td><code>acceptEdits</code></td><td>Auto-approve edit operations, other operations like command execution still ask</td><td>When you only want to allow file editing, commands still need confirmation</td></tr><tr><td><strong>Auto-Accept</strong> (Bypass)</td><td><code>bypassPermissions</code></td><td>Auto-approve all operations</td><td>When you fully trust Claude</td></tr></tbody></table><p><strong>Difference Between Configuration Value and Display Name</strong>: <code>Shift+Tab</code> cycles through display names; <code>settings.json</code> <code>defaultMode</code> uses configuration values. They correspond one-to-one, but format differs (camelCase vs. lowercase-with-hyphens).</p><p><strong>Evolution Trend</strong>: From August 2026, Auto mode became the new default for Pro/Max/Team plans — officially finding that the AI classifier&#39;s recognition rate for dangerous commands is sufficiently high, and the cost of Normal mode being flooded by popups outweighs the cost of occasionally blocking low-value operations.</p><p><strong>Official Docs</strong>: <a href="https://code.claude.com/docs/en/permissions" target="_blank" rel="noreferrer">Permission Reference</a></p><hr><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./claude-code.html">Claude Code Main Tutorial</a> — Installation, interaction, how to use core features</li><li><a href="./claude-code-cheatsheet.html">Claude Code Cheatsheet</a> — Configuration/decision tables/data source quick reference</li><li><a href="./claude-code-cookbook.html">Practical Workflow Cookbook</a> — Prompt patterns for 9 daily development scenarios</li></ul>`,152)])])}const k=t(n,[["render",r]]);export{b as __pageData,k as default};
